source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full-width horizontal color bars encode a vertical cycle.
    bars = {}
    for r, row in enumerate(grid):
        vals = {v for v in row if v}
        if len(vals) == 1 and all(v != 0 for v in row):
            bars[r] = next(iter(vals))
    if bars:
        key_color = bars
        coord = lambda r, c: r
    else:
        # Parallel diagonal traces encode values by their line intercept.
        groups = []
        for kind in ("sum", "diff"):
            d = {}
            for r in range(h):
                for c in range(w):
                    v = grid[r][c]
                    if v:
                        k = r + c if kind == "sum" else c - r
                        d.setdefault(k, []).append(v)
            # The intended direction has long, monochromatic diagonal traces.
            score = (max(map(len, d.values()), default=0), sum(len(x) ** 2 for x in d.values()))
            groups.append((score, kind, d))
        _, kind, d = max(groups, key=lambda x: x[0])
        key_color = {}
        for k, vals in d.items():
            counts = {v: vals.count(v) for v in set(vals)}
            key_color[k] = max(counts, key=counts.get)
        coord = (lambda r, c: r + c) if kind == "sum" else (lambda r, c: c - r)

    # The line offsets specify one complete repeating cycle. Pick the smallest
    # cycle length that maps every residue to exactly one observed color.
    period = None
    residues = None
    for p in range(1, max(h, w) + 1):
        m = {}
        valid = True
        for k, color in key_color.items():
            q = k % p
            if q in m and m[q] != color:
                valid = False
                break
            m[q] = color
        if valid and len(m) == p:
            period, residues = p, m
            break
    if period is None:
        # Normally the encoded cycle covers every residue; this keeps a
        # partially visible cycle continuous if its traces meet the borders.
        period = max(1, len(key_color))
        residues = {k % period: v for k, v in key_color.items()}
        ordered = sorted(residues)
        for q in range(period):
            if q not in residues:
                residues[q] = residues[ordered[0]]
    return [[residues[coord(r, c) % period] for c in range(w)] for r in range(h)]
